/**
 * All business logic reads time through a Clock so late/half-day/QR-expiry/finalization
 * rules can be tested without sleeping. In production this is always the system clock;
 * the value is generated by the server, never taken from a client.
 */
export interface Clock {
  now(): Date;
}

export const systemClock: Clock = { now: () => new Date() };

export function fixedClock(at: Date | string): Clock & { set(next: Date | string): void } {
  let current = new Date(at);
  return {
    now: () => new Date(current),
    set(next) {
      current = new Date(next);
    },
  };
}
